package org.usbworkbench;
import java.io.*;
import java.util.*;
public class ExpansionTest {
 static int checks;static void check(boolean c){checks++;if(!c)throw new AssertionError("check "+checks);}interface A{void run()throws Exception;}static void fails(String code,A a)throws Exception{try{a.run();throw new AssertionError(code);}catch(IOException e){check(e.getMessage().startsWith(code));}}
 static DiskTools.Progress p=(a,b)->{};
 static byte[] request(int op,long at,int n,byte[] payload)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();o.write(new byte[]{85,66,87,49,(byte)op});for(int i=0;i<8;i++)o.write((byte)(at>>>(8*i)));for(int i=0;i<4;i++)o.write((byte)(n>>>(8*i)));if(payload!=null)o.write(payload);return o.toByteArray();}
 static void rpc()throws Exception{DiskToolsTest.MemoryDisk corrupt=new DiskToolsTest.MemoryDisk(4,512){@Override public void write(long at,byte[] b,int n)throws IOException{byte[] altered=b.clone();altered[0]^=1;super.write(at,altered,n);}};fails("VERIFY_FAILED",()->NativeProtocol.serve(new ByteArrayInputStream(request(2,0,512,new byte[512])),new ByteArrayOutputStream(),corrupt,true,p));for(int sector:new int[]{512,4096}){DiskToolsTest.MemoryDisk d=new DiskToolsTest.MemoryDisk(64,sector);byte[] fill=new byte[sector];Arrays.fill(fill,(byte)7);d.write(0,fill,sector);byte[] data=new byte[17001];new Random(55).nextBytes(data);NativeProtocol.writeBytes(d,31,data);byte[] actual=new byte[data.length];NativeProtocol.readBytes(d,31,actual);check(Arrays.equals(data,actual));check(d.at(0)[30]==7);ByteArrayOutputStream out=new ByteArrayOutputStream();NativeProtocol.serve(new ByteArrayInputStream(request(1,31,data.length,null)),out,d,false,p);check(out.size()==data.length+8);int writes=d.writes;fails("ENGINE_READ_ONLY",()->NativeProtocol.serve(new ByteArrayInputStream(request(2,0,3,new byte[3])),new ByteArrayOutputStream(),d,false,p));check(writes==d.writes);fails("DISK_BOUNDS",()->NativeProtocol.serve(new ByteArrayInputStream(request(1,64L*sector-2,3,null)),out,d,false,p));fails("ENGINE_PROTOCOL",()->NativeProtocol.serve(new ByteArrayInputStream(request(3,0,1,null)),out,d,true,p));fails("ENGINE_PROTOCOL",()->NativeProtocol.serve(new ByteArrayInputStream(request(1,0,1048577,null)),out,d,true,p));SliceDevice slice=new SliceDevice(d,5,8);fails("DISK_BOUNDS",()->slice.write(7,new byte[sector*2],sector*2));check(writes==d.writes);slice.write(0,fill,sector);check(d.at(5)[0]==7);}}
 static void parts()throws Exception{byte[] data=new byte[2500123];new Random(5).nextBytes(data);List<byte[]> bytes=new ArrayList<>();WorkshopTools.split(new ByteArrayInputStream(data),data.length,1048576,index->new ByteArrayOutputStream(){public void close(){bytes.add(toByteArray());}},p);check(bytes.size()==3);List<WorkshopTools.Part> parts=new ArrayList<>();for(byte[] b:bytes)parts.add(new WorkshopTools.Part(()->new ByteArrayInputStream(b)));Collections.reverse(parts);ByteArrayOutputStream out=new ByteArrayOutputStream();WorkshopTools.join(parts,out,p);check(Arrays.equals(data,out.toByteArray()));parts.remove(0);fails("PART_MISSING",()->WorkshopTools.join(parts,new ByteArrayOutputStream(),p));parts.clear();for(byte[] b:bytes)parts.add(new WorkshopTools.Part(()->new ByteArrayInputStream(b)));bytes.get(1)[100]^=1;fails("PART_CORRUPT",()->WorkshopTools.join(parts,new ByteArrayOutputStream(),p));parts.add(parts.get(0));fails("PART_MISSING",()->WorkshopTools.join(parts,new ByteArrayOutputStream(),p));fails("SOURCE_SHORT",()->WorkshopTools.split(new ByteArrayInputStream(new byte[100]),101,1048576,index->new ByteArrayOutputStream(),p));fails("PART_INVALID",()->new WorkshopTools.Part(()->new ByteArrayInputStream(new byte[24])));}
 static void fat()throws Exception{new File("artifacts/native-fixtures").mkdirs();for(int bits:new int[]{12,16})for(String table:new String[]{"mbr","gpt"}){long sectors=bits==12?8192:131072;DiskToolsTest.MemoryDisk d=new DiskToolsTest.MemoryDisk(sectors,512);AdvancedDiskTools.format(d,"fat"+bits,table,"TEST_USB",0,p);check(new String(d.at(2048),54,8,"US-ASCII").equals("FAT"+bits+"   "));if(table.equals("gpt"))check(AdvancedDiskTools.inspectGpt(d).contains("CRC OK"));else check((d.at(0)[450]&255)==(bits==12?1:14));try(RandomAccessFile f=new RandomAccessFile("artifacts/native-fixtures/fat"+bits+"-"+table+".img","rw")){f.setLength((sectors-2048-(table.equals("gpt")?33:0))*512);for(Map.Entry<Long,byte[]> e:d.sectors.entrySet())if(e.getKey()>=2048&&e.getKey()<sectors-(table.equals("gpt")?33:0)){f.seek((e.getKey()-2048)*512);f.write(e.getValue());}}}
 DiskToolsTest.MemoryDisk d=new DiskToolsTest.MemoryDisk(9000000,512);fails("FAT16_SIZE",()->AdvancedDiskTools.format(d,"fat16","gpt","USB",0,p));check(d.writes==0);fails("FAT12_SIZE",()->AdvancedDiskTools.format(d,"fat12","mbr","USB",0,p));check(d.writes==0);}
 static void readTools()throws Exception{DiskToolsTest.MemoryDisk d=new DiskToolsTest.MemoryDisk(4096,512);check(WorkshopTools.randomRead(d,p).contains("Random read"));check(WorkshopTools.scan(d,p).contains("readable"));check(WorkshopTools.hex(d).contains("0000"));check(d.writes==0);byte[] image=new byte[65536];image[510]=0x55;image[511]=(byte)0xaa;System.arraycopy("CD001".getBytes("US-ASCII"),0,image,32769,5);String r=WorkshopTools.inspectImage(new ByteArrayInputStream(image),image.length,p);check(r.contains("MBR signature")&&r.contains("ISO9660"));}
 static void cloneTest()throws Exception{DiskToolsTest.MemoryDisk source=new DiskToolsTest.MemoryDisk(65,512),target=new DiskToolsTest.MemoryDisk(65,512);byte[] b=new byte[512];new Random(8).nextBytes(b);source.write(64,b,512);int before=source.writes;DiskCloner.clone(source,target,p);check(Arrays.equals(source.at(64),target.at(64)));check(source.writes==before);fails("CLONE_SAME",()->DiskCloner.clone(source,source,p));DiskToolsTest.MemoryDisk larger=new DiskToolsTest.MemoryDisk(66,512);fails("CLONE_GEOMETRY",()->DiskCloner.clone(source,larger,p));check(larger.writes==0);DiskToolsTest.MemoryDisk lying=new DiskToolsTest.MemoryDisk(65,512){@Override public void read(long lba,byte[] bytes,int n)throws IOException{super.read(lba,bytes,n);if(lba==64)bytes[0]^=1;}};fails("VERIFY_FAILED",()->DiskCloner.clone(source,lying,p));}
 static void hashes()throws Exception{String expected="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad";String result=WorkshopTools.checksums(new ByteArrayInputStream("abc".getBytes("US-ASCII")),3,expected,p);check(result.contains("MD5: 900150983cd24fb0d6963f7d28e17f72"));check(result.contains("SHA-1: a9993e364706816aba3e25717850c26c9cd0d89d"));check(result.contains("SHA-256 MATCH"));check(result.contains("ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a"));result=WorkshopTools.checksums(new ByteArrayInputStream(new byte[0]),0,expected,p);check(result.contains("MISMATCH"));fails("HASH_EXPECTED",()->WorkshopTools.checksums(new ByteArrayInputStream(new byte[0]),0,"123",p));}
 static void largeCluster()throws Exception{DiskToolsTest.MemoryDisk d=new DiskToolsTest.MemoryDisk(4194304,512);AdvancedDiskTools.format(d,"exfat","gpt","LARGE",65536,p);check(d.at(2048)[109]==16);check(AdvancedDiskTools.inspectGpt(d).contains("CRC OK"));try(RandomAccessFile f=new RandomAccessFile("artifacts/native-fixtures/exfat-largecluster.img","rw")){f.setLength((d.count-2048-33)*512);for(Map.Entry<Long,byte[]> e:d.sectors.entrySet())if(e.getKey()>=2048&&e.getKey()<d.count-33){f.seek((e.getKey()-2048)*512);f.write(e.getValue());}}}
 static void cancelStreams()throws Exception{IoRegistry io=new IoRegistry();java.util.concurrent.CountDownLatch started=new java.util.concurrent.CountDownLatch(1),closed=new java.util.concurrent.CountDownLatch(1);InputStream stream=io.input(new InputStream(){public int read()throws IOException{started.countDown();try{if(!closed.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new IOException("timeout");}catch(InterruptedException e){throw new IOException(e);}return -1;}public void close(){closed.countDown();}});Thread reader=new Thread(()->{try{stream.read();}catch(IOException e){throw new RuntimeException(e);}});reader.start();check(started.await(2,java.util.concurrent.TimeUnit.SECONDS));io.cancelAsync();reader.join(2000);check(!reader.isAlive());check(io.size()==0);stream.close();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(OutputStream out=io.output(bytes)){out.write(new byte[]{1,2,3});check(io.size()==1);}check(Arrays.equals(bytes.toByteArray(),new byte[]{1,2,3})&&io.size()==0);}
 public static void main(String[] args)throws Exception{rpc();parts();fat();readTools();cloneTest();hashes();largeCluster();cancelStreams();System.out.println("PASS: "+checks+" expansion protocol, FAT12/16, split corruption, bounds and read-only tool checks");}
}
